variants.code_sketch:
let numbers = AsyncStream<Int> { continuation in
    let task = Task {
        var n = 0
        while !Task.isCancelled { continuation.yield(n); n += 1 }
        continuation.finish()
    }
    continuation.onTermination = { _ in task.cancel() }   // cleanup
}

for await n in numbers { if n > 4 { break }; print(n) }   // break cancels
